const parseBody = (value) => {
  if (!value) return null;
  if (typeof value === 'object') return value;
  if (typeof value === 'string') {
    try {
      return JSON.parse(value);
    } catch {
      return null;
    }
  }
  return null;
};

let featureArtifacts = input;
if (typeof featureArtifacts === 'string') {
  try {
    featureArtifacts = JSON.parse(featureArtifacts);
  } catch {
    featureArtifacts = [];
  }
}
if (!Array.isArray(featureArtifacts)) featureArtifacts = [];

const competitorArtifacts = Array.isArray(context?.list_competitors?.artifacts)
  ? context.list_competitors.artifacts
  : [];

const ourFeatures = featureArtifacts.map((item) => {
  const body = parseBody(item?.content) || {};
  return {
    logicalId: item?.logicalId || body?.logicalId || '',
    title: body?.title || item?.title || '',
    description: body?.description || '',
    keyword: body?.keyword || '',
    category: body?.category || item?.category || '',
    sourceArtifacts: Array.isArray(body?.sourceArtifacts) ? body.sourceArtifacts : [],
    competitorInsights: Array.isArray(body?.competitorInsights) ? body.competitorInsights : [],
  };
});

const competitors = competitorArtifacts.map((item) => {
  const body = parseBody(item?.content);
  return {
    logicalId: item?.logicalId || '',
    title: item?.title || '',
    category: item?.category || '',
    tags: item?.tags || [],
    content: body ?? item?.content ?? '',
  };
});

return {
  ourFeatures,
  competitors,
  featureCount: ourFeatures.length,
  competitorCount: competitors.length,
  featuresJson: JSON.stringify(ourFeatures, null, 2),
};

