const slugify = (value) => String(value || 'feature').toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '') || 'feature';

const root = context?.enrich_features && typeof context.enrich_features === 'object' ? context.enrich_features : {};
const competitorLogicalId = root.competitorLogicalId || context?.prepare_competitor?.logicalId || '';
const competitorName = root.competitorName || context?.prepare_competitor?.title || '';

let features = input;
if (typeof features === 'string') {
  try {
    features = JSON.parse(features);
  } catch {
    features = [];
  }
}
if (!Array.isArray(features)) features = [];

const used = new Set();

return features.map((feature, featureIndex) => {
  const keyword = slugify(feature?.keyword || feature?.title || `feature-${featureIndex + 1}`);
  let logicalId = feature?.logicalId || `feature-${keyword}`;
  if (!feature?.logicalId && feature?.isNew) {
    logicalId = `feature-${keyword}`;
  }
  if (used.has(logicalId)) logicalId = `${logicalId}-${featureIndex + 1}`;
  used.add(logicalId);

  const category = slugify(feature?.category || 'product-features');

  const insight = {
    competitorLogicalId,
    competitorName,
    notes: feature?.competitiveNotes || '',
    differentiation: feature?.differentiation || '',
  };

  return {
    logicalId,
    title: feature?.title || `Feature ${featureIndex + 1}`,
    description: feature?.description || '',
    keyword,
    category,
    sourceArtifacts: Array.isArray(feature?.sourceArtifacts) ? feature.sourceArtifacts : [],
    competitorInsights: [insight],
    isNew: Boolean(feature?.isNew),
    competitorLogicalId,
    competitorName,
    tags: `feature,prd,competitive,${keyword},${category},product`,
  };
});

const parseBody = (value) => {
  if (!value) return null;
  if (typeof value === 'object') return value;
  if (typeof value === 'string') {
    try {
      return JSON.parse(value);
    } catch {
      return null;
    }
  }
  return null;
};

const incoming = input && typeof input === 'object' ? input : {};
const existingDoc = context?.check_existing?.content ?? context?.check_existing?.artifact?.content;
const existing = parseBody(existingDoc) || {};
const latestInsight = Array.isArray(incoming.competitorInsights) ? incoming.competitorInsights[0] : null;

const entry = {
  competitorLogicalId: incoming.competitorLogicalId || latestInsight?.competitorLogicalId || '',
  competitorName: incoming.competitorName || latestInsight?.competitorName || '',
  notes: latestInsight?.notes || incoming.competitiveNotes || '',
  differentiation: latestInsight?.differentiation || incoming.differentiation || '',
};

const insights = Array.isArray(existing.competitorInsights) ? [...existing.competitorInsights] : [];
const insightIndex = insights.findIndex((row) => row?.competitorLogicalId === entry.competitorLogicalId);
if (insightIndex >= 0) insights[insightIndex] = entry;
else insights.push(entry);

const merged = {
  logicalId: incoming.logicalId || existing.logicalId || '',
  title: incoming.title || existing.title || '',
  description: incoming.description || existing.description || '',
  keyword: incoming.keyword || existing.keyword || '',
  category: incoming.category || existing.category || '',
  sourceArtifacts: Array.isArray(incoming.sourceArtifacts) && incoming.sourceArtifacts.length
    ? incoming.sourceArtifacts
    : (Array.isArray(existing.sourceArtifacts) ? existing.sourceArtifacts : []),
  competitorInsights: insights,
  tags: incoming.tags || existing.tags || '',
};

return merged;
